WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, status ORDER BY paid_at DESC NULLS LAST, id) AS rn FROM payments QUALIFY rn = 1) SELECT CASE WHEN amount >= 1250 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, COUNT_IF(method = 'promptpay') AS promptpay_events, COUNT(*) FILTER (WHERE status = 'FAILED') AS failed_rows, SUM(CASE WHEN status = 'FAILED' THEN amount ELSE 0 END) AS failed_amount FROM deduped GROUP BY 1 ORDER BY failed_amount DESC NULLS LAST;
